                     src="@Model.ImageUrl"
                     alt="@Model.ImageAltText"
                     width="1800"
                     height="1200" />
                @if (!string.IsNullOrWhiteSpace(Model.ImageCredit))
                {
                    <figcaption class="mt-3 text-right text-xs text-zinc-500">@Model.ImageCredit</figcaption>
                }
            </figure>
        }
    </div>
</section>
