===== Views/Shared/Components/BlogPostList/Default.cshtml
@model Umbraco.Bench.Umbraco.Models.Blog.BlogPostListModel

<section class="mx-auto max-w-7xl px-6 py-16 lg:px-10 lg:py-24">
    <div class="mb-10 grid gap-5 lg:grid-cols-[0.8fr_1.2fr] lg:items-end">
        <h2 class="text-4xl font-black tracking-[-0.04em] text-zinc-950 sm:text-5xl">@Model.Heading</h2>
        <p class="max-w-2xl text-lg leading-8 text-zinc-600 lg:justify-self-end">@Model.Introduction</p>
    </div>

    <div class="grid gap-7 md:grid-cols-2">
        @foreach (var post in Model.Posts)
        {
            <article class="group overflow-hidden rounded-[1.75rem] border border-zinc-200 bg-white shadow-sm transition duration-300 hover:-translate-y-1 hover:shadow-xl hover:shadow-zinc-200/70">
                <a href="@post.Url" class="block">
                    @if (!string.IsNullOrWhiteSpace(post.ImageUrl))
                    {
                        <img class="aspect-[8/5] w-full object-cover transition duration-500 group-hover:scale-[1.025]"
                             src="@post.ImageUrl"
                             alt="@post.ImageAltText"
                             width="1200"
                             height="750"
                             loading="lazy" />
                    }
                    <div class="p-7 sm:p-9">
                        <time class="text-xs font-black tracking-[0.2em] text-cyan-700 uppercase" datetime="@post.PublishedDate.ToString("yyyy-MM-dd")">
                            @post.PublishedDate.ToString("d MMMM yyyy")
                        </time>
                        <h3 class="mt-4 text-3xl leading-tight font-black tracking-[-0.035em] text-zinc-950">@post.Title</h3>
                        <p class="mt-4 leading-7 text-zinc-600">@post.Summary</p>
                        <span class="mt-7 inline-flex items-center gap-2 text-sm font-black text-zinc-950">
                            Read field note <span aria-hidden="true" class="transition-transform group-hover:translate-x-1">&rarr;</span>
                        </span>
                    </div>
                </a>
            </article>
        }
    </div>
</section>
