@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel

<section class="relative overflow-hidden bg-zinc-950 text-white">
    <div class="absolute inset-0 bg-[radial-gradient(circle_at_top_left,rgba(34,211,238,0.16),transparent_42%)]"></div>
    <div class="relative mx-auto grid max-w-7xl gap-10 px-6 py-16 lg:grid-cols-[0.92fr_1.08fr] lg:items-center lg:px-10 lg:py-24">
        <div class="max-w-2xl">
            @if (!string.IsNullOrWhiteSpace(Model.Eyebrow))
            {
                <p class="mb-5 text-xs font-black tracking-[0.25em] text-cyan-300 uppercase">@Model.Eyebrow</p>
            }
            <h1 class="text-5xl leading-[0.98] font-black tracking-[-0.055em] text-balance sm:text-6xl lg:text-7xl">@Model.Heading</h1>
            @if (!string.IsNullOrWhiteSpace(Model.Introduction))
            {
                <p class="mt-7 max-w-xl text-lg leading-8 text-zinc-300 sm:text-xl">@Model.Introduction</p>
            }
        </div>

        @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
        {
            <figure class="relative">
                <div class="absolute -inset-4 rotate-2 rounded-[2rem] border border-cyan-300/20"></div>
                <img class="relative aspect-[3/2] w-full rounded-[1.5rem] object-cover shadow-2xl shadow-cyan-950/50"
                     src="@Model.ImageUrl"
                     alt="@Model.ImageAltText"
                     width="1800"
                     height="1200" />
                @if (!string.IsNullOrWhiteSpace(Model.ImageCredit))
                {
                    <figcaption class="mt-3 text-right text-xs text-zinc-500">@Model.ImageCredit</figcaption>
                }
            </figure>
        }
    </div>
</section>
